<?php $title='Administrar rifas'; ?><div class="level"><div><h1 class="title">Administrar rifas</h1><p class="subtitle is-6">Cierre y sorteo solo cuando se haya vendido la meta de boletos.</p></div></div><div class="box"><div class="table-container"><table class="table is-fullwidth is-hoverable"><thead><tr><th>Rifa</th><th>Producto</th><th>Boleto</th><th>Vendidos/meta</th><th>Estado</th><th>Ganador</th><th></th></tr></thead><tbody><?php foreach($raffles as $r): ?><tr><td><?= e($r['code']) ?></td><td><?= e($r['product_name']) ?></td><td><?= money($r['ticket_price']) ?></td><td><?= (int)$r['sold_count'] ?>/<?= (int)$r['tickets_to_target'] ?></td><td><span class="tag <?= $r['status']==='open'?'is-success':'is-danger' ?>"><?= e($r['status']) ?></span></td><td><?= $r['winner_ticket_id'] ? '#'.e($r['winner_ticket_id']) : '—' ?></td><td><?php if($r['status']==='open' && (int)$r['sold_count'] >= (int)$r['tickets_to_target']): ?><form method="post" action="<?= route('admin_draw') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="button is-small is-warning">Cerrar y sortear</button></form><?php else: ?><span class="has-text-grey">Auto al completar</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
